use split_decls_genesis :: ourprelude :: * ; use crate :: fmt ; use crate :: future :: Future ; use crate :: pin :: Pin ; use crate :: task :: { Context , Poll } ; #[doc = " Creates a future that wraps a function returning [`Poll`]."] #[doc = ""] #[doc = " Polling the future delegates to the wrapped function. If the returned future is pinned, then the"] #[doc = " captured environment of the wrapped function is also pinned in-place, so as long as the closure"] #[doc = " does not move out of its captures it can soundly create pinned references to them."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " ```"] #[doc = " # async fn run() {"] #[doc = " use core::future::poll_fn;"] #[doc = " use std::task::{Context, Poll};"] #[doc = ""] #[doc = " fn read_line(_cx: &mut Context<'_>) -> Poll<String> {"] #[doc = "     Poll::Ready(\"Hello, World!\".into())"] #[doc = " }"] #[doc = ""] #[doc = " let read_future = poll_fn(read_line);"] #[doc = " assert_eq!(read_future.await, \"Hello, World!\".to_owned());"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " ## Capturing a pinned state"] #[doc = ""] #[doc = " Example of a closure wrapping inner futures:"] #[doc = ""] #[doc = " ```"] #[doc = " # async fn run() {"] #[doc = " use core::future::{self, Future};"] #[doc = " use core::task::Poll;"] #[doc = ""] #[doc = " /// Resolves to the first future that completes. In the event of a tie, `a` wins."] #[doc = " fn naive_select<T>("] #[doc = "     a: impl Future<Output = T>,"] #[doc = "     b: impl Future<Output = T>,"] #[doc = " ) -> impl Future<Output = T>"] #[doc = " {"] #[doc = "     let (mut a, mut b) = (Box::pin(a), Box::pin(b));"] #[doc = "     future::poll_fn(move |cx| {"] #[doc = "         if let Poll::Ready(r) = a.as_mut().poll(cx) {"] #[doc = "             Poll::Ready(r)"] #[doc = "         } else if let Poll::Ready(r) = b.as_mut().poll(cx) {"] #[doc = "             Poll::Ready(r)"] #[doc = "         } else {"] #[doc = "             Poll::Pending"] #[doc = "         }"] #[doc = "     })"] #[doc = " }"] #[doc = ""] #[doc = " let a = async { 42 };"] #[doc = " let b = future::pending();"] #[doc = " let v = naive_select(a, b).await;"] #[doc = " assert_eq!(v, 42);"] #[doc = ""] #[doc = " let a = future::pending();"] #[doc = " let b = async { 27 };"] #[doc = " let v = naive_select(a, b).await;"] #[doc = " assert_eq!(v, 27);"] #[doc = ""] #[doc = " let a = async { 42 };"] #[doc = " let b = async { 27 };"] #[doc = " let v = naive_select(a, b).await;"] #[doc = " assert_eq!(v, 42); // biased towards `a` in case of tie!"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = " This time without [`Box::pin`]ning:"] #[doc = ""] #[doc = " [`Box::pin`]: ../../std/boxed/struct.Box.html#method.pin"] #[doc = ""] #[doc = " ```"] #[doc = " # async fn run() {"] #[doc = " use core::future::{self, Future};"] #[doc = " use core::pin::pin;"] #[doc = " use core::task::Poll;"] #[doc = ""] #[doc = " /// Resolves to the first future that completes. In the event of a tie, `a` wins."] #[doc = " fn naive_select<T>("] #[doc = "     a: impl Future<Output = T>,"] #[doc = "     b: impl Future<Output = T>,"] #[doc = " ) -> impl Future<Output = T>"] #[doc = " {"] #[doc = "     async {"] #[doc = "         let (mut a, mut b) = (pin!(a), pin!(b));"] #[doc = "         future::poll_fn(move |cx| {"] #[doc = "             if let Poll::Ready(r) = a.as_mut().poll(cx) {"] #[doc = "                 Poll::Ready(r)"] #[doc = "             } else if let Poll::Ready(r) = b.as_mut().poll(cx) {"] #[doc = "                 Poll::Ready(r)"] #[doc = "             } else {"] #[doc = "                 Poll::Pending"] #[doc = "             }"] #[doc = "         }).await"] #[doc = "     }"] #[doc = " }"] #[doc = ""] #[doc = " let a = async { 42 };"] #[doc = " let b = future::pending();"] #[doc = " let v = naive_select(a, b).await;"] #[doc = " assert_eq!(v, 42);"] #[doc = " # }"] #[doc = " ```"] #[doc = ""] #[doc = "   - Notice how, by virtue of being in an `async` context, we have been able to make the [`pin!`]"] #[doc = "     macro work, thereby avoiding any need for the `unsafe`"] #[doc = "     <code>[Pin::new_unchecked](&mut fut)</code> constructor."] #[doc = ""] #[doc = " [`pin!`]: crate::pin::pin!"] #[stable (feature = "future_poll_fn" , since = "1.64.0")] pub fn poll_fn < T , F > (f : F) -> PollFn < F > where F : FnMut (& mut Context < '_ >) -> Poll < T > , { PollFn { f } } #[doc = " A Future that wraps a function returning [`Poll`]."] #[doc = ""] #[doc = " This `struct` is created by [`poll_fn()`]. See its"] #[doc = " documentation for more."] #[must_use = "futures do nothing unless you `.await` or poll them"] #[stable (feature = "future_poll_fn" , since = "1.64.0")] pub struct PollFn < F > { f : F , } #[stable (feature = "future_poll_fn" , since = "1.64.0")] impl < F : Unpin > Unpin for PollFn < F > { } #[stable (feature = "future_poll_fn" , since = "1.64.0")] impl < F > fmt :: Debug for PollFn < F > { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { f . debug_struct ("PollFn") . finish () } } #[stable (feature = "future_poll_fn" , since = "1.64.0")] impl < T , F > Future for PollFn < F > where F : FnMut (& mut Context < '_ >) -> Poll < T > , { type Output = T ; fn poll (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < T > { (unsafe { & mut self . get_unchecked_mut () . f }) (cx) } }